from common_e16 import *
import ast,numpy as np

def main():
 assert not (R/'PREREGISTRATION_SEAL.json').exists()
 assert read(R/'00_integrity/INTEGRITY_PASS.json')['passed']
 assert read(R/'09_resource_preflight/XGBOOST_RUNTIME_READY.json')['passed']
 for p in (R/'src').glob('*.py'):ast.parse(p.read_text(encoding='utf-8-sig'))
 m={a['path']:a for a in read(K/'REPRODUCIBILITY_MANIFEST.json')['files']};extra=[]
 for p in [K/'ORIGINAL_TILE_TOPOLOGY.csv']+[Path(a['core_path']) for a in rows(R/'01_frozen_dataset/GEOMETRY_REGISTRY.csv')]:
  expected=m[p.relative_to(K).as_posix()];assert sha(p)==expected.get('SHA256',expected.get('sha256'));extra.append(dict(path=str(p),SHA256=sha(p),passed=True))
 table(R/'00_integrity/ADDITIONAL_CORE_HASH_AUDIT.csv',extra)
 blocks=[dict(block='A',channels='0;1;2',meaning='visible-domain centering'),dict(block='B',channels='6;7;8;18',meaning='visible-domain spans, including duplicated Z span'),dict(block='C',channels='16;17',meaning='visible-domain normal XY standard deviations')];table(R/'FEATURE_BLOCK_CONTRACT.csv',blocks)
 cells=[]
 for s in ['000','100','010','001','110','101','011','111']:cells.append(dict(cell='F'+s,A=int(s[0]),B=int(s[1]),C=int(s[2]),context='X50;X43',oracle_diagnostic_only=bool(int(s,2))))
 table(R/'BLOCK_FACTORIAL_MATRIX.csv',cells)
 descriptions=[('query_anchor_X','(X-query-plan center X)/60','dimensionless'),('query_anchor_Y','(Y-query-plan center Y)/60','dimensionless'),('local_anchor_Z','(Z-nearest visible anchor Z)/60','dimensionless'),('normal_X','visible normal oriented positive canonical Z','dimensionless'),('normal_Y','visible normal oriented positive canonical Z','dimensionless'),('normal_Z','visible normal oriented positive canonical Z','dimensionless'),('local_span_X','ptp visible16neighbor X/60','dimensionless'),('local_span_Y','ptp visible16neighbor Y/60','dimensionless'),('local_span_Z','ptp visible16neighbor Z/60','dimensionless'),('load_X','1','dimensionless'),('load_Y','0','dimensionless'),('load_Z','0','dimensionless'),('front_tag','0','dimensionless'),('height_relief','Z query-mean visible16neighbor Z','mm'),('normal_variation','norm(normal query-mean visible16neighbor normal)','dimensionless'),('incident_area','log1p(visible triangle incident area / 1mm2)','dimensionless'),('local_normal_std_X','population std visible16neighbor normal X','dimensionless'),('local_normal_std_Y','population std visible16neighbor normal Y','dimensionless'),('local_Z_std','population std visible16neighbor Z /60','dimensionless')]
 table(R/'OBSERVABLE_N3_FEATURE_CONTRACT.csv',[dict(channel=i,name=a,formula=b,units=c,support='current visible measured surface, frozen geometric query plan and documented canonical loading frame',hidden_full_geometry=False,target_derived=False) for i,(a,b,c) in enumerate(descriptions)])
 def md(name,text):(R/name).write_text(text,encoding='utf8')
 md('OBSERVABLE_FEATURE_CONTRACT.md','''# Frozen N3 observable geometry contract
The nineteen formulas are authoritative in OBSERVABLE_N3_FEATURE_CONTRACT.csv and src/features_e16.py. All neighborhoods retain the current observed geometry's historical 16-neighbor indices; context4096 and three neighborhood scales remain unchanged. No FE values or full-domain statistics enter inputs. Visible incident triangle area is geometric, not a stress-derived weight. Population standard deviations use ddof=0.

The XY datum is the already declared original query-plan tile center in the registered canonical measurement frame. Its Z is the nearest currently visible XY vertex, with minimum canonical-ID tie breaking within1e-12mm2. Required XY distance <=1mm. This datum is a local operational measurement/query datum, not an independently surveyed physical datum. Query plan and canonical registration are required inputs; no registration independence is claimed. Five tile anchors are used for FULL as well as cropped conditions. This is a representation-frame change; the architecture, original query ownership and single prediction per query remain S0. FULL's common observed geometry/context is reused, but features are instantiated per query tile. Cropped inputs never read the full feature table.

Missing local support is not synthesized. Visible neighborhoods, normals and triangle areas can legitimately change at observation boundaries. Qualification must report actual changes rather than assert invariance. Any mandatory unavailable channel blocks N3 production; no redesign after outcomes.
''')
 n3=dict(model='N3_OBSERVABLE_GEOMETRY_PT',architecture='SurfacePT S1',parameters=7228,width=24,blocks=1,features=19,context_points=4096,neighbors_per_scale=16,scales='historical nearest16,1mm,3mm',seeds=[20261021,20261022],folds=['F1','F2','F3','F4','F5'],epochs=80,optimizer='AdamW',lr=.001,weight_decay=.0001,scheduler='CosineAnnealingLR',eta_min=1e-5,gradient_clip_norm=1,queries_per_source_epoch=512,target_normalization_MPa=100,context_probabilities=dict(FULL=1/3,X50=1/3,X43=1/3),checkpoint_policy='final epoch80 only',initialization='random from scratch',source_step_weight='n_train_sources/(4*n_sources_on_training_plate)',query_sampling='original area CDF with replacement',architecture_change=False,dryrun='one backward finite-gradient check; ZERO optimizer steps; discarded random model',maximum_fits=10)
 write(R/'N3_ARCHITECTURE_AND_TRAINING.json',n3)
 write(R/'XGBOOST_BASELINE_PROTOCOL.json',dict(model='B2_GEOMETRY_XGBOOST',version='3.0.2',parameters=dict(objective='reg:squarederror',n_estimators=500,max_depth=6,learning_rate=.05,subsample=.8,colsample_bytree=.8,reg_lambda=1.,tree_method='hist',random_state=20261021,n_jobs=2),maximum_fits=5,maximum_queries_per_source_context=1024,sampling='1024 unique original-area CDF midpoint strata per source; same IDs in each context',weights='equal4trainingplates/equal sources/3contexts/equal area-CDF strata; normalize mean weight1 for regularization',features='exact same N3 contract',no_early_stopping=True))
 write(R/'METRIC_DEFINITIONS.json',dict(primary_policy='S0',target='QUALIFIED_FINE_M2_V1_T2',nominal_MPa=100,weights='original T0 areas',L2='sqrt(sum w*(p-y)^2 / sum w*y^2)',MAE='sum w*abs(p-y)/sum w',RMSE='sqrt(sum w*(p-y)^2/sum w)',high95='stable value sort, interpolate weighted cumulative area at.95, own-field >= thresholds',FN_area='sum original area where reference high and prediction not high',FP_area='sum original area where prediction high and reference not high',regions='frozen E13 original source-region definitions',aggregation='source mean within plate then unweighted mean of five plates; both seeds separate, metric arithmetic mean only',factorial_effect='sum product of +/-1 factor signs times response /4; pair effect=half DID, triple=quarter DID; nonlinear metrics not variance attribution',secondary_stitching='NOT_EXECUTED; fixed primary S0 only',B0_B1_restricted='NOT_EVALUATED'))
 r=gate();write(R/'RESOURCE_BUDGET.json',dict(maximum_workspace_GiB=16,estimated_workspace_GiB=4,minimum_E_free_GiB=20,minimum_C_free_GiB=2,minimum_RAM_free_GiB=3,minimum_commit_free_GiB=3,parallel_workers=1,torch_threads=2,XGB_threads=2,factorial_fields=832,N3_fits=10,XGB_fits=5,N3_optimizer_steps=8320,N3_dry_backward_steps=1,automatic_replacement_fits=0,preflight=r))
 md('RESEARCH_CLOSURE_RULES.md','''# Frozen scientific closure rules
Close after the authorized matrix, or documented mandatory gate failure. No R8-E17 is authorized. No hyperparameter search, replacement fit, seed selection, new ANSYS or new source identity.

METHOD_IMPROVEMENT_SUPPORTED requires both-seed-mean N3 L2 to improve N2 by >=5% in each of FULL/X50/X43, no context High95 IoU degradation >0.02, no context FN-area increase >10%, and no context peak or Q95 absolute amplitude-error increase >10%. METHOD_IMPROVEMENT_MIXED applies to any >=5% L2 context benefit or >=0.02 IoU context benefit that fails the joint safeguards. Otherwise METHOD_IMPROVEMENT_NOT_SUPPORTED. These thresholds are reporting rules, not statistical significance or physical-validation tests. Any incomplete mandatory experiment/audit is FINAL_COMPARISON_INCOMPLETE (machine decision COMPARISON_INCOMPLETE). B2 superiority or inconsistency across plates limits architectural-value claims regardless of this code. Report both seeds, all difficult plates and amplitude/localization tradeoffs. No fresh independent generalization, experimental stress or industrial deployment claim.
''')
 md('R8E16_EXPERIMENT_PROTOCOL.md','''# R8-E16 final finite experimental protocol
Status: EXPLORATORY_FINAL_METHOD_DEVELOPMENT on previously examined13sources/5plates. Frozen before new factorial outcomes and N3/B2 training. Historical integrity scope is the consumed critical artifact subset, not every E15 bulk export.

Order: historical integrity; freeze all contracts; frozen N1/N2 eight-cell block factorial (832fields), F000/F111 historical replay; geometry-only N3 qualification; one no-update backward dry run; ten sequential80epoch random-initialized N3 fits and held-out full-core predictions; five fixed XGBoost fits; metrics and independent audits; manuscript and closure. No configuration is selected from new held-out scores. Historical N1/N2 fields reused; B0/B1 FULL only reused. All new fields use original34200core points/source and own-field weighted High95. The frozen query-tile geometry is an operational input; it is not hidden complete-source metadata.

Keep model context, neighbors, original query ownership and weights fixed in factorial; only blocks A/B/C replaced with full-source values by exact original IDs. Oracle interventions are nondeployable diagnostic distribution shifts. Preserve feature/target/point manifests and actual runtime batches. N3/B2 use only visible data, with fixed registered measurement/loading frame. Original source T0 weights are used for evaluation and training quadrature, not hidden predictive labels. Training and held-out plates must remain disjoint at actual runtime.

All training/evaluation choices are frozen in companion files. Only future scoring/reporting/independent-audit code may be added without changing this experimental seal. Any execution correction must be disclosed, hashed and limited to the same run/configuration, never a better-score replacement.
''')
 paths=['R8E16_EXPERIMENT_PROTOCOL.md','BLOCK_FACTORIAL_MATRIX.csv','OBSERVABLE_FEATURE_CONTRACT.md','OBSERVABLE_N3_FEATURE_CONTRACT.csv','FEATURE_BLOCK_CONTRACT.csv','N3_ARCHITECTURE_AND_TRAINING.json','XGBOOST_BASELINE_PROTOCOL.json','FROZEN_LOPO_SPLITS.csv','METRIC_DEFINITIONS.json','RESOURCE_BUDGET.json','RESEARCH_CLOSURE_RULES.md','01_frozen_dataset/ORIGINAL_TILE_TOPOLOGY.csv','01_frozen_dataset/GEOMETRY_REGISTRY.csv','HISTORICAL_MODEL_HASHES.csv']+['src/'+a for a in ['common_e16.py','model_e3.py','base_arch.py','features_e16.py','train_e16.py','factorial_e16.py','infer_n3_e16.py','xgb_e16.py']]
 write(R/'PREREGISTRATION_SEAL.json',dict(UTC=now(),before_new_intervention_outcomes=True,before_N3_training=True,before_XGB_fitting=True,files=[dict(path=p,SHA256=sha(R/p)) for p in paths]));print('PREREGISTRATION_SEALED',sha(R/'PREREGISTRATION_SEAL.json'),flush=True)
if __name__=='__main__':main()
